//! 📇️ Bounded source-qualified scalar frame metadata and exact borrowed-key indexing.
use super::{FlowBounds,FlowFrame,FlowFrameContext,FlowFrameSource,flow_frame_from_model};
use semio_s_artifact_layout_layout_model::{Frame,snapshot::LayoutSnapshot};
use semio_framework_value::{numeric_scratch::NumericIndex,RetirementDemand,RetainedCloneGrant,ValueRefusalKind};
use super::super::metadata_index::{MetadataIndex,MetadataKey as Key,MetadataSource,MetadataLookup};
#[derive(Clone,Copy,Debug,Default,PartialEq,Eq)]
pub struct FlowProjectionGrant{pub maximum_source_items:u32,pub maximum_copy_bytes:usize,pub maximum_capacity_bytes:usize,pub maximum_depth:usize}
#[derive(Clone,Copy,Debug,Default,PartialEq,Eq)]
pub struct FlowProjectionReceipt{pub source_items:usize,pub copied_bytes:usize,pub allocated_bytes:usize,pub released_bytes:usize}
#[derive(Clone,Copy,Debug,PartialEq,Eq)]
pub enum FlowProjectionStep{Progress,Ready,Cancelled}
#[derive(Clone,Copy,Debug,PartialEq,Eq)]
pub struct FlowFrameAddress{pub page_index:usize,pub frame_index:usize,pub parent_index:Option<usize>,pub override_index:Option<usize>,pub story_index:usize,pub next:Option<usize>,pub predecessor:Option<usize>,pub head:usize,pub visible:bool,pub locked:bool}
#[derive(Clone,Copy)]
struct Row{page:usize,frame:usize,parent:Option<usize>,over:Option<usize>,story:usize,next:Option<usize>,predecessor:Option<usize>,head:Option<usize>,seen:bool}
#[derive(Clone,Copy)]
struct PageRange{parent_base:usize,parent_count:usize,local_base:usize,local_count:usize}

struct KeySource<'a>{doc:&'a LayoutSnapshot,rows:&'a NumericIndex<usize,Row>}
impl MetadataSource for KeySource<'_>{
 fn identity(&self)->usize{self.doc as*const LayoutSnapshot as usize}
 fn text(&self,key:Key)->Result<&str,&'static str>{let doc=self.doc;let frame=||{let row=self.rows.get(&key.a).ok_or("layout.flow.projection.row")?;match row.parent{Some(parent)=>doc.parent_pages.get(parent).and_then(|page|page.frames.get(row.frame)),None=>doc.pages.get(row.page).and_then(|page|page.frames.get(row.frame))}.ok_or("layout.flow.projection.frame")};match key.kind{0=>doc.stories.get(key.a).map(|story|story.id.as_str()).ok_or("layout.flow.projection.story"),1=>doc.parent_pages.get(key.a).map(|page|page.id.as_str()).ok_or("layout.flow.projection.parent"),2|7=>Ok(frame()?.id()),3=>doc.pages.get(key.a).and_then(|page|page.overrides.get(key.b)).map(|over|over.object_id.as_str()).ok_or("layout.flow.projection.override"),4=>doc.pages.get(key.a).and_then(|page|page.parent_page_id.as_deref()).ok_or("layout.flow.projection.parent"),5=>match frame()?{Frame::Text{story_id,..}=>Ok(story_id),_=>Err("layout.flow.projection.text")},6=>match frame()?{Frame::Text{thread_next,..}=>thread_next.as_deref().ok_or("layout.flow.projection.next"),_=>Err("layout.flow.projection.text")},_=>Err("layout.flow.projection.key")}}
}
/// 📚️ Retains only paged scalar metadata; the immutable snapshot and its strings stay with the original caller.
pub struct FlowProjection{metadata:MetadataIndex,rows:NumericIndex<usize,Row>,locations:NumericIndex<usize,usize>,pages:NumericIndex<usize,PageRange>,source:Option<usize>,phase:u8,cursor:usize,page:usize,parent:Option<usize>,frame:usize,ordinal:usize,raw:usize,walk:Option<usize>,active_head:Option<usize>,visited:usize,cancelled:bool,last:FlowProjectionReceipt}
impl Default for FlowProjection{fn default()->Self{Self::new()}}
impl FlowProjection{
 pub fn new()->Self{Self{metadata:MetadataIndex::new(),rows:NumericIndex::new(),locations:NumericIndex::new(),pages:NumericIndex::new(),source:None,phase:0,cursor:0,page:0,parent:None,frame:0,ordinal:0,raw:0,walk:None,active_head:None,visited:0,cancelled:false,last:Default::default()}}
 pub fn len(&self)->usize{self.rows.len()}
 pub fn is_empty(&self)->bool{self.len()==0}
 pub fn ready(&self)->bool{self.phase==12&&!self.cancelled}
 pub fn last_receipt(&self)->FlowProjectionReceipt{self.last}
 fn row(&self,at:usize)->Result<Row,&'static str>{self.rows.get(&at).copied().ok_or("layout.flow.projection.row")}
 fn put(&mut self,at:usize,row:Row)->Result<(),&'static str>{self.last.copied_bytes+=std::mem::size_of::<Row>();self.rows.insert_reserved(at,row).map(|_|()).map_err(|_|"layout.flow.projection.reserved")}
 fn original<'a>(&self,doc:&'a LayoutSnapshot,row:Row)->Result<&'a Frame,&'static str>{match row.parent{Some(parent)=>doc.parent_pages.get(parent).and_then(|p|p.frames.get(row.frame)),None=>doc.pages.get(row.page).and_then(|p|p.frames.get(row.frame))}.ok_or("layout.flow.projection.frame")}
 fn text<'a>(&self,doc:&'a LayoutSnapshot,at:usize)->Result<(&'a str,Option<&'a str>),&'static str>{match self.original(doc,self.row(at)?)?{Frame::Text{story_id,thread_next,..}=>Ok((story_id,thread_next.as_deref())),_=>Err("layout.flow.projection.text")}}
 fn reserve<K:Copy+Ord,V>(index:&mut NumericIndex<K,V>,grant:FlowProjectionGrant,last:&mut FlowProjectionReceipt)->Result<bool,&'static str>{let quote=index.next_allocation_bytes().map_err(|_|"layout.flow.projection.capacity")?;if quote==0{return Ok(false)}let progress=index.reserve_one_funded(RetainedCloneGrant{maximum_items:grant.maximum_source_items as usize,maximum_copy_bytes:grant.maximum_copy_bytes,maximum_capacity_bytes:grant.maximum_capacity_bytes,maximum_release_bytes:0,maximum_depth:grant.maximum_depth}).map_err(|error|{last.allocated_bytes+=error.allocated_bytes;"layout.flow.projection.allocation"})?;last.allocated_bytes+=progress.retained_capacity_bytes;last.copied_bytes+=progress.copied_bytes;Ok(true)}

 fn query(&mut self,doc:&LayoutSnapshot,key:Key,domain:u8,scope:usize,insert:Option<usize>,grant:FlowProjectionGrant)->Result<Option<Option<usize>>,&'static str>{let result=self.metadata.query(&KeySource{doc,rows:&self.rows},key,domain,scope,insert,RetainedCloneGrant{maximum_items:grant.maximum_source_items as usize,maximum_copy_bytes:grant.maximum_copy_bytes,maximum_capacity_bytes:grant.maximum_capacity_bytes,maximum_release_bytes:0,maximum_depth:grant.maximum_depth});let receipt=self.metadata.last_receipt();self.last.allocated_bytes+=receipt.retained_capacity_bytes;self.last.copied_bytes+=receipt.copied_bytes;match result.map_err(|error|if error.kind==ValueRefusalKind::InvalidValue&&insert.is_some(){"layout.flow.projection.duplicate"}else{"layout.flow.projection.metadata"})?{MetadataLookup::Pending=>Ok(None),MetadataLookup::Ready(value)=>Ok(Some(value))}}
 fn reserve_demand<K:Copy+Ord,V>(index:&NumericIndex<K,V>)->Result<RetirementDemand,&'static str>{let mut demand=index.next_reserve_demand().map_err(|_|"layout.flow.projection.capacity")?;demand.depth=demand.depth.max(1);Ok(demand)}
 fn index_demand(&self)->Result<RetirementDemand,&'static str>{self.metadata.next_demand().map_err(|_|"layout.flow.projection.capacity")}
 fn admit_demand(&self,doc:&LayoutSnapshot,parent:Option<usize>)->Result<RetirementDemand,&'static str>{let frame=match parent{Some(parent)=>doc.parent_pages[parent].frames.get(self.frame),None=>doc.pages[self.page].frames.get(self.frame)};let mut demand=RetirementDemand{depth:1,..Default::default()};let Some(frame)=frame else{if parent.is_some(){demand.copy_bytes=std::mem::size_of::<PageRange>();}return Ok(demand)};if !matches!(frame,Frame::Text{..}){return Ok(demand)}if self.rows.get(&self.ordinal).is_none(){demand=Self::reserve_demand(&self.rows)?;if demand.capacity_bytes==0{demand.copy_bytes=std::mem::size_of::<Row>();}}else if self.locations.get(&self.raw).is_none(){demand=Self::reserve_demand(&self.locations)?;if demand.capacity_bytes==0{demand.copy_bytes=std::mem::size_of::<usize>();}}else{return self.index_demand();}Ok(demand)}
 pub fn next_advance_demand(&self,doc:&LayoutSnapshot)->Result<RetirementDemand,&'static str>{if self.source.is_some_and(|source|source!=doc as*const LayoutSnapshot as usize){return Err("layout.flow.projection.stale-source");}let mut demand=RetirementDemand{depth:1,..Default::default()};if self.cancelled||self.ready(){return Ok(demand)}match self.phase{0|1|2=>return self.index_demand(),3=>{if self.cursor==doc.pages[self.page].overrides.len(){if self.pages.get(&self.page).is_none(){demand=Self::reserve_demand(&self.pages)?;if demand.capacity_bytes==0{demand.copy_bytes=std::mem::size_of::<PageRange>();}}}else{return self.index_demand();}},4=>{return match self.parent{Some(parent)=>self.admit_demand(doc,Some(parent)),None=>Ok(RetirementDemand{copy_bytes:std::mem::size_of::<PageRange>(),..demand})};},5=>return self.admit_demand(doc,None),7 if self.cursor<self.len()=>{demand=self.index_demand()?;demand.copy_bytes+=std::mem::size_of::<Row>();},8=>{if self.row(self.cursor)?.parent.is_some(){demand=self.index_demand()?;demand.copy_bytes+=std::mem::size_of::<Row>();}},9=>{if self.text(doc,self.cursor)?.1.is_some(){demand=self.index_demand()?;demand.copy_bytes+=std::mem::size_of::<Row>();}},10 if self.cursor<self.len()=>{if self.row(self.cursor)?.next.is_some(){demand.copy_bytes=std::mem::size_of::<Row>();}},11 if self.walk.is_some()=>demand.copy_bytes=std::mem::size_of::<Row>(),_=>{}}Ok(demand)}
 pub fn next_advance_capacity_bytes(&self,doc:&LayoutSnapshot)->Result<usize,&'static str>{Ok(self.next_advance_demand(doc)?.capacity_bytes)}
 fn increment_raw(&mut self)->Result<(),&'static str>{self.raw=self.raw.checked_add(1).ok_or("layout.flow.projection.address")?;Ok(())}
 fn admit(&mut self,doc:&LayoutSnapshot,parent:Option<usize>,grant:FlowProjectionGrant)->Result<bool,&'static str>{let frame=match parent{Some(parent)=>doc.parent_pages[parent].frames.get(self.frame),None=>doc.pages[self.page].frames.get(self.frame)};let Some(frame)=frame else{return Ok(true)};if !matches!(frame,Frame::Text{..}){self.frame+=1;self.increment_raw()?;return Ok(false)}if self.ordinal>u32::MAX as usize{return Err("layout.flow.projection.address")}if self.rows.get(&self.ordinal).is_none(){if Self::reserve(&mut self.rows,grant,&mut self.last)?{return Ok(false)}self.put(self.ordinal,Row{page:self.page,frame:self.frame,parent,over:None,story:0,next:None,predecessor:None,head:None,seen:false})?;return Ok(false)}if self.locations.get(&self.raw).is_none(){if Self::reserve(&mut self.locations,grant,&mut self.last)?{return Ok(false)}self.last.copied_bytes+=std::mem::size_of::<usize>();self.locations.insert_reserved(self.raw,self.ordinal).map_err(|_|"layout.flow.projection.reserved")?;return Ok(false)}if self.query(doc,Key{kind:2,a:self.ordinal,b:0},2,if parent.is_some(){self.page+1}else{0},Some(self.ordinal),grant)?.is_some(){self.ordinal+=1;self.frame+=1;self.increment_raw()?;}Ok(false)}
 /// 👣️ Debits one source scalar/header/index operation or one separately admitted original block.
 pub fn advance(&mut self,doc:&LayoutSnapshot,grant:FlowProjectionGrant)->Result<FlowProjectionStep,&'static str>{
  self.last=Default::default();if self.cancelled{return Ok(FlowProjectionStep::Cancelled)}let demand=self.next_advance_demand(doc)?;if self.ready(){return Ok(FlowProjectionStep::Ready)}if grant.maximum_source_items==0||grant.maximum_copy_bytes<demand.copy_bytes||grant.maximum_capacity_bytes<demand.capacity_bytes||grant.maximum_depth<demand.depth{return Ok(FlowProjectionStep::Progress)}let source=doc as *const LayoutSnapshot as usize;if self.source.is_some_and(|old|old!=source){return Err("layout.flow.projection.stale-source")}self.source=Some(source);self.last.source_items=1;
  match self.phase{
   0=>{if self.cursor==doc.stories.len(){self.cursor=0;self.phase=1;}else if self.query(doc,Key{kind:0,a:self.cursor,b:0},0,0,Some(self.cursor),grant)?.is_some(){self.cursor+=1;}},
   1=>{if self.cursor==doc.parent_pages.len(){self.cursor=0;self.phase=2;}else if self.query(doc,Key{kind:1,a:self.cursor,b:0},1,0,Some(self.cursor),grant)?.is_some(){self.cursor+=1;}},
   2=>{if self.page==doc.pages.len(){self.cursor=0;self.phase=7;}else{if self.page>u32::MAX as usize{return Err("layout.flow.projection.address")}if doc.pages[self.page].parent_page_id.is_none(){self.parent=None;self.cursor=0;self.phase=3;}else if let Some(value)=self.query(doc,Key{kind:4,a:self.page,b:0},1,0,None,grant)?{self.parent=Some(value.ok_or("layout.flow.projection.parent")?);self.cursor=0;self.phase=3;}}},
   3=>{if self.cursor==doc.pages[self.page].overrides.len(){if self.pages.get(&self.page).is_none(){if !Self::reserve(&mut self.pages,grant,&mut self.last)?{self.last.copied_bytes+=std::mem::size_of::<PageRange>();self.pages.insert_reserved(self.page,PageRange{parent_base:self.raw,parent_count:self.parent.map_or(0,|p|doc.parent_pages[p].frames.len()),local_base:0,local_count:doc.pages[self.page].frames.len()}).map_err(|_|"layout.flow.projection.reserved")?;}}else{self.frame=0;self.phase=4;}}else if self.query(doc,Key{kind:3,a:self.page,b:self.cursor},3,self.page,Some(self.cursor),grant)?.is_some(){self.cursor+=1;}},
   4=>{if self.parent.is_none()||self.admit(doc,self.parent,grant)?{let mut range=*self.pages.get(&self.page).ok_or("layout.flow.projection.page")?;range.local_base=self.raw;self.last.copied_bytes+=std::mem::size_of::<PageRange>();self.pages.insert_reserved(self.page,range).map_err(|_|"layout.flow.projection.reserved")?;self.frame=0;self.phase=5;}},
   5=>{if self.admit(doc,None,grant)?{self.page+=1;self.phase=2;}},
   7=>{if self.cursor==self.len(){self.cursor=0;self.phase=10;}else if let Some(value)=self.query(doc,Key{kind:5,a:self.cursor,b:0},0,0,None,grant)?{let mut row=self.row(self.cursor)?;row.story=value.ok_or("layout.flow.projection.story")?;self.put(self.cursor,row)?;self.phase=8;}},
   8=>{let mut row=self.row(self.cursor)?;if row.parent.is_none(){self.phase=9;}else if let Some(value)=self.query(doc,Key{kind:7,a:self.cursor,b:0},3,row.page,None,grant)?{row.over=value;self.put(self.cursor,row)?;self.phase=9;}},
   9=>{let mut row=self.row(self.cursor)?;if self.text(doc,self.cursor)?.1.is_none(){self.cursor+=1;self.phase=7;}else if let Some(value)=self.query(doc,Key{kind:6,a:self.cursor,b:0},2,if row.parent.is_some(){row.page+1}else{0},None,grant)?{row.next=Some(value.ok_or("layout.flow.projection.next")?);self.put(self.cursor,row)?;self.cursor+=1;self.phase=7;}},
   10=>{if self.cursor==self.len(){self.cursor=0;self.phase=11;}else{let row=self.row(self.cursor)?;if let Some(at)=row.next{let mut next=self.row(at)?;if next.story!=row.story{return Err("layout.flow.projection.story")}if next.predecessor.is_some(){return Err("layout.flow.projection.fork")}next.predecessor=Some(self.cursor);self.put(at,next)?;}self.resolved(doc,self.cursor)?;self.cursor+=1;}},
   11=>{if let Some(at)=self.walk{let mut row=self.row(at)?;if row.seen{return Err("layout.flow.projection.cycle")}row.seen=true;row.head=self.active_head;self.put(at,row)?;self.visited+=1;self.walk=row.next;}else if self.cursor==self.len(){if self.visited!=self.len(){return Err("layout.flow.projection.cycle")}self.phase=12;}else{let at=self.cursor;self.cursor+=1;if self.row(at)?.predecessor.is_none(){self.active_head=Some(at);self.walk=Some(at);}}},
   _=>return Err("layout.flow.projection.phase")
  }Ok(if self.ready(){FlowProjectionStep::Ready}else{FlowProjectionStep::Progress})
 }
 fn resolved(&self,doc:&LayoutSnapshot,index:usize)->Result<FlowFrame,&'static str>{let row=self.row(index)?;let original=self.original(doc,row)?;let mut frame=flow_frame_from_model(original,FlowFrameContext{page_index:row.page,frame_index:row.frame,parent:row.parent.is_some(),story_index:row.story,next:row.next,gutter:doc.pages[row.page].columns.gutter})?;if let Some(bounds)=row.over.and_then(|at|doc.pages[row.page].overrides[at].bounds.as_ref()){frame.bounds=FlowBounds{x:bounds.x,y:bounds.y,width:bounds.width,height:bounds.height,rotation:bounds.rotation};frame.validate()?;}Ok(frame)}
 pub fn source_view<'a>(&'a self,doc:&'a LayoutSnapshot)->Result<FlowProjectionView<'a>,&'static str>{if !self.ready()||self.source!=Some(doc as *const LayoutSnapshot as usize){return Err("layout.flow.projection.not-ready")}Ok(FlowProjectionView{owner:self,doc})}
 pub fn ordinal(&self,page:usize,parent:bool,frame:usize)->Option<usize>{if !self.ready(){return None}let range=self.pages.get(&page)?;let(base,count)=if parent{(range.parent_base,range.parent_count)}else{(range.local_base,range.local_count)};if frame>=count{return None}self.locations.get(&base.checked_add(frame)?).copied()}
 pub fn is_head(&self,index:usize)->bool{self.ready()&&self.rows.get(&index).is_some_and(|row|row.predecessor.is_none())}
 pub fn address(&self,doc:&LayoutSnapshot,index:usize)->Result<Option<FlowFrameAddress>,&'static str>{self.source_view(doc)?;let Some(row)=self.rows.get(&index).copied() else{return Ok(None)};let frame=self.original(doc,row)?;let over=row.over.map(|at|&doc.pages[row.page].overrides[at]);Ok(Some(FlowFrameAddress{page_index:row.page,frame_index:row.frame,parent_index:row.parent,override_index:row.over,story_index:row.story,next:row.next,predecessor:row.predecessor,head:row.head.ok_or("layout.flow.projection.head")?,visible:over.and_then(|o|o.visible).unwrap_or_else(||frame.visible()),locked:over.and_then(|o|o.locked).unwrap_or_else(||frame.locked())}))}

 pub fn cancel(&mut self){self.cancelled=true;self.source=None;self.metadata.cancel();}
 pub fn next_release_bytes(&self)->Result<usize,&'static str>{if !self.rows.terminal_is_empty(){self.rows.next_close_release_byte_demand().map_err(|_|"layout.flow.projection.release")}else if !self.locations.terminal_is_empty(){self.locations.next_close_release_byte_demand().map_err(|_|"layout.flow.projection.release")}else if !self.pages.terminal_is_empty(){self.pages.next_close_release_byte_demand().map_err(|_|"layout.flow.projection.release")}else{self.metadata.next_close_release_bytes().map_err(|_|"layout.flow.projection.release")}}
 pub fn next_copy_bytes(&self)->usize{if !self.rows.terminal_is_empty(){self.rows.next_close_copy_byte_demand()}else if !self.locations.terminal_is_empty(){self.locations.next_close_copy_byte_demand()}else if !self.pages.terminal_is_empty(){self.pages.next_close_copy_byte_demand()}else{self.metadata.next_close_copy_bytes()}}
 pub fn close_one(&mut self,maximum_items:usize,maximum_copy_bytes:usize,maximum_release_bytes:usize)->Result<FlowProjectionReceipt,&'static str>{self.cancel();if self.rows.terminal_is_empty()&&self.locations.terminal_is_empty()&&self.pages.terminal_is_empty(){let p=self.metadata.close_one(RetainedCloneGrant{maximum_items,maximum_copy_bytes,maximum_capacity_bytes:0,maximum_release_bytes,maximum_depth:1}).map_err(|_|"layout.flow.projection.release")?;self.last=FlowProjectionReceipt{source_items:p.copied_items,copied_bytes:p.copied_bytes,allocated_bytes:p.retained_capacity_bytes,released_bytes:p.released_bytes};return Ok(self.last);}let copy=self.next_copy_bytes();let progress=if !self.rows.terminal_is_empty(){self.rows.close_copy_step_funded(maximum_items,maximum_copy_bytes,maximum_release_bytes)}else if !self.locations.terminal_is_empty(){self.locations.close_copy_step_funded(maximum_items,maximum_copy_bytes,maximum_release_bytes)}else{self.pages.close_copy_step_funded(maximum_items,maximum_copy_bytes,maximum_release_bytes)}.map_err(|_|"layout.flow.projection.release")?;self.last=FlowProjectionReceipt{source_items:usize::from(progress.progressed),copied_bytes:if progress.progressed{copy}else{0},allocated_bytes:0,released_bytes:progress.released_allocation_bytes};Ok(self.last)}
 pub fn terminal_is_empty(&self)->bool{self.cancelled&&self.rows.terminal_is_empty()&&self.locations.terminal_is_empty()&&self.pages.terminal_is_empty()&&self.metadata.terminal_is_empty()}

}
/// 🧭️ Borrows the prepared owner and original snapshot for one fixed scalar lookup.
pub struct FlowProjectionView<'a>{owner:&'a FlowProjection,doc:&'a LayoutSnapshot}
impl FlowFrameSource for FlowProjectionView<'_>{fn len(&self)->usize{self.owner.len()}fn get(&self,index:usize)->Option<FlowFrame>{self.owner.rows.get(&index)?;self.owner.resolved(self.doc,index).ok()}}
